mapper.sql:
WHERE TRUE
 AND (LOCATE(#{q},p.real_name)>0 OR LOCATE(#{q},m.position)>0 OR LOCATE(#{q},m.affiliation)>0)
 AND ()=#{status}
 AND (CASE WHEN EXISTS(SELECT 1 FROM person_account_binding b WHERE b.person_id=m.person_id AND b.status='ACTIVE') THEN 'BOUND' ELSE 'UNBOUND' END)=#{bindingState}

FROM comment c JOIN post p ON p.id=c.target_id
 WHERE c.target_type=1 AND c.parent_id IS NULL AND p.post_type='MENTOR_QA'
 AND c.user_id=#{author}
